function startPlayback() {
  state.phase = "playback";
  state.last_feedback = "";
  emit("playback_started", {});
  var seq = state.sequence;
  var i = 0;
  function step() {
    if (i >= seq.length) {
      currentHighlight = null;
      state.phase = "input";
      emit("input_phase_started", {});
      return;
    }
    currentHighlight = seq[i];
    setTimeout(function () {
      currentHighlight = null;
      setTimeout(function () {
        i += 1;
        step();
      }, GAP_MS);
    }, HIGHLIGHT_MS);
  }
  step();
}

function doReset(seed) {
  if (typeof seed === "number") currentSeed = seed;
  eventEpoch += 1;
  eventSeq = 0;
  events = [];
  currentHighlight = null;
  state = {
    status: "menu",
    phase: "menu",
    round: 1,
    lives: 3,
    score: 0,
    progress: 0,
    sequence: [],
    last_feedback: ""
  };
  emit("game_reset", {});
}
